// dealStore.js — reads the seed dataset (generated by scripts/build-data.js)
// and overlays AI-refreshed deals from data/deals-live.json.
// Seed is an artifact: never hand-edit data/deals.json — edit scripts/build-data.js.

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA = path.join(__dirname, '..', '..', 'data');
const SEED = path.join(DATA, 'deals.json');
const LIVE = path.join(DATA, 'deals-live.json');

function readJson(p, fallback) {
  try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch { return fallback; }
}

export function getMarkets() {
  return readJson(SEED, { markets: [] }).markets;
}

export function getSources() {
  return readJson(path.join(DATA, 'sources.json'), { sources: [] });
}

// Verified outbound-link registry. Shipped with every /api/deals response so
// cards can build their link rows without a second round trip.
export function getLinks() {
  return readJson(path.join(DATA, 'links.json'), { stores: {}, apps: {} });
}

// Live refreshed deals replace seed deals for the markets they were fetched for.
export function getDeals() {
  const seed = readJson(SEED, { deals: [], markets: [], updatedAt: null });
  const live = readJson(LIVE, { refreshes: {} });
  const refreshedMarkets = Object.keys(live.refreshes || {});
  let deals = seed.deals.slice();
  const liveDeals = [];
  for (const mkt of refreshedMarkets) {
    const entry = live.refreshes[mkt];
    if (!entry?.deals?.length) continue;
    // Drop seed deals scoped ONLY to refreshed markets; keep multi-market seed deals.
    deals = deals.filter(d => !(d.markets.every(m => refreshedMarkets.includes(m))));
    liveDeals.push(...entry.deals);
  }
  return {
    updatedAt: seed.updatedAt,
    week: seed.week,
    markets: seed.markets,
    sbg: seed.sbg,
    badgeStyle: seed.badgeStyle,
    links: getLinks(),
    refreshes: Object.fromEntries(refreshedMarkets.map(m => [m, live.refreshes[m].refreshedAt])),
    deals: [...liveDeals, ...deals],
  };
}

export function saveRefresh(market, deals) {
  const live = readJson(LIVE, { refreshes: {} });
  live.refreshes[market] = { refreshedAt: new Date().toISOString(), deals };
  fs.writeFileSync(LIVE, JSON.stringify(live, null, 1));
  return live.refreshes[market];
}

export function clearRefresh(market) {
  const live = readJson(LIVE, { refreshes: {} });
  if (market === 'all') live.refreshes = {};
  else delete live.refreshes[market];
  fs.writeFileSync(LIVE, JSON.stringify(live, null, 1));
}
